{{!-- Styling parameters: class, titleClass, descriptionClass, buttonClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Component: Member CTA | Usage: inside {{#post}} after {{content}} --}}
{{#if @site.members_enabled}}
<aside class="ghcn-member-cta{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}">
    {{#if access}}
        {{#if @member}}
            <span class="ghcn-badge">Member access</span>
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">You’re all caught up</h2>
            <p class="ghcn-member-cta__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">Manage your subscription, email preferences, and account details in Portal.</p>
            <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/account" data-portal="account">Manage account</a>
        {{else}}
            {{#if @site.allow_self_signup}}
            <span class="ghcn-badge">Join the publication</span>
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">Enjoying this story?</h2>
            <p class="ghcn-member-cta__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">Subscribe for new posts and member updates delivered directly to your inbox.</p>
            <div class="ghcn-member-cta__actions"><a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/signup" data-portal="signup">Subscribe</a><a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--ghost" href="#/portal/signin" data-portal="signin">Sign in</a></div>
            {{else}}
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">Already a member?</h2>
            <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/signin" data-portal="signin">Sign in</a>
            {{/if}}
        {{/if}}
    {{else}}
        {{#if @member.paid}}
            <span class="ghcn-badge">Account required</span>
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">This post isn’t included in your plan</h2>
            <p class="ghcn-member-cta__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">Open your account to review your membership and available plans.</p>
            <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/account" data-portal="account">Manage account</a>
        {{else if @member}}
            {{#if @site.paid_members_enabled}}
            {{#if @site.allow_self_signup}}
            <span class="ghcn-badge">Paid members</span>
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">Upgrade to continue reading</h2>
            <p class="ghcn-member-cta__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">Review the available plans to find one that includes this post.</p>
            <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/account/plans" data-portal="account/plans">Upgrade membership</a>
            {{else}}
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">This post requires a different membership</h2>
            <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/account" data-portal="account">Manage account</a>
            {{/if}}
            {{else}}
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">This post is not available with your membership</h2>
            <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/account" data-portal="account">Manage account</a>
            {{/if}}
        {{else}}
            <span class="ghcn-badge">Members only</span>
            <h2 class="ghcn-member-cta__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">Continue reading with a membership</h2>
            <p class="ghcn-member-cta__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">This post requires a membership with access. Already a member? Sign in to continue.</p>
            <div class="ghcn-member-cta__actions">{{#if @site.allow_self_signup}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/signup" data-portal="signup">View memberships</a>{{/if}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="#/portal/signin" data-portal="signin">Sign in</a></div>
        {{/if}}
    {{/if}}
</aside>
{{/if}}
{{/with}}

/* ghostcn: Member CTA */
.ghcn-member-cta { box-sizing: border-box; min-width: 0; margin-block: var(--ghcn-section-space, clamp(24px, 4vw, 48px)); font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); box-sizing: border-box; min-width: 0; overflow-wrap: anywhere; border: 1px solid var(--border, #e4e4e7); border-radius: var(--ghcn-panel-radius, min(var(--radius, 8px), 24px)); background: var(--card, #fff); color: var(--card-foreground, #09090b); width: min(100% - 32px, 704px); margin-inline: auto; padding: var(--ghcn-panel-padding, clamp(16px, 3vw, 24px)); text-align: center; }
.ghcn-member-cta *, .ghcn-member-cta *::before, .ghcn-member-cta *::after { box-sizing: border-box; }
.ghcn-member-cta__title { font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance; margin: 12px 0 8px; color: inherit; }
.ghcn-member-cta__description { max-width: 60ch; margin: 0 auto 16px; color: var(--muted-foreground); font-size: var(--ghcn-text-small, 14px); }
.ghcn-member-cta__actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 0.75em; }
